solution.solution.cpp:
#include <cstdint>
#include <set>
#include <vector>

namespace
{
    int sequenceDifference(std::uint16_t a, std::uint16_t b)
    {
        return static_cast<std::int16_t>(static_cast<std::uint16_t>(a - b));
    }
}

class ReceivedPackets
{
public:
    void record(std::uint16_t sequence)
    {
        if (!any_)
        {
            any_ = true;
            ack_ = sequence;
            return;
        }
        const int d{ sequenceDifference(sequence, ack_) };
        if (d > 0)
        {
            if (d > 32) bits_ = 0;
            else
            {
                const std::uint64_t moved{ (std::uint64_t{ bits_ } << d) | (std::uint64_t{ 1 } << (d - 1)) };
                bits_ = static_cast<std::uint32_t>(moved & 0xFFFFFFFFu);
            }
            ack_ = sequence;
        }
        else if (d < 0 && -d - 1 < 32)
        {
            bits_ |= 1u << (-d - 1);
        }
    }

    std::uint16_t ack() const { return ack_; }
    std::uint32_t ackBits() const { return bits_; }

private:
    bool any_{ false };
    std::uint16_t ack_{ 0 };
    std::uint32_t bits_{ 0 };
};

class SentPackets
{
public:
    void sent(std::uint16_t sequence) { waiting_.insert(sequence); }

    std::vector<std::uint16_t> onAck(std::uint16_t ack, std::uint32_t ackBits)
    {
        std::vector<std::uint16_t> delivered;
        for (int i{ 31 }; i >= -1; --i)
        {
            if (i >= 0 && (ackBits & (1u << i)) == 0) continue;
            const auto sequence{ static_cast<std::uint16_t>(ack - 1 - i) };
            if (waiting_.erase(sequence) > 0) delivered.push_back(sequence);
        }
        return delivered;
    }

private:
    std::set<std::uint16_t> waiting_;
};

unitTests:
TEST("receiving in order and with gaps") {
    ReceivedPackets r;
    CHECK_EQ(r.ack(), 0); CHECK_EQ(r.ackBits(), 0u);
    r.record(100);
    CHECK_EQ(r.ack(), 100); CHECK_EQ(r.ackBits(), 0u);
    r.record(101);
    CHECK_EQ(r.ack(), 101); CHECK_EQ(r.ackBits(), 1u);
    r.record(103);
    CHECK_EQ(r.ack(), 103); CHECK_EQ(r.ackBits(), 6u);
    r.record(102);
    CHECK_EQ(r.ack(), 103); CHECK_EQ(r.ackBits(), 7u);
    r.record(102);
    r.record(103);
    CHECK_EQ(r.ack(), 103); CHECK_EQ(r.ackBits(), 7u);
}
TEST("big jumps and very late packets") {
    ReceivedPackets r;
    r.record(200);
    r.record(232);
    CHECK_EQ(r.ackBits(), 0x80000000u);
    r.record(199);
    CHECK_EQ(r.ackBits(), 0x80000000u);
    r.record(201);
    CHECK_EQ(r.ackBits(), 0xC0000000u);
    r.record(270);
    CHECK_EQ(r.ack(), 270); CHECK_EQ(r.ackBits(), 0u);
}
TEST("receiving across the wrap") {
    ReceivedPackets r;
    r.record(65535);
    r.record(1);
    CHECK_EQ(r.ack(), 1); CHECK_EQ(r.ackBits(), 2u);
    r.record(0);
    CHECK_EQ(r.ackBits(), 3u);
}
TEST("the sender learns what arrived, once") {
    SentPackets s;
    for (std::uint16_t q{ 10 }; q <= 13; ++q) s.sent(q);
    CHECK(s.onAck(13, 0b101) == (std::vector<std::uint16_t>{ 10, 12, 13 }));
    CHECK(s.onAck(13, 0b111) == (std::vector<std::uint16_t>{ 11 }));
    CHECK(s.onAck(13, 0b111).empty());
    CHECK(s.onAck(500, 0xFFFFFFFFu).empty());
}
TEST("the sender across the wrap") {
    SentPackets s;
    s.sent(65534); s.sent(65535); s.sent(0);
    CHECK(s.onAck(0, 0b11) == (std::vector<std::uint16_t>{ 65534, 65535, 0 }));
    s.sent(65535);
    CHECK(s.onAck(65535, 0) == (std::vector<std::uint16_t>{ 65535 }));
}
TEST("both halves together") {
    ReceivedPackets r;
    SentPackets s;
    for (std::uint16_t q{ 0 }; q < 40; ++q) {
        s.sent(q);
        if (q % 7 != 3) r.record(q);
    }
    const auto delivered{ s.onAck(r.ack(), r.ackBits()) };
    CHECK_EQ(delivered.size(), 28u);
    CHECK_EQ(delivered.back(), 39);
    CHECK_EQ(delivered.front(), 7);
}

